do $test$
declare child uuid:=gen_random_uuid(); older uuid:=gen_random_uuid(); dossier uuid:=gen_random_uuid(); dossier2 uuid:=gen_random_uuid(); other_project uuid:=gen_random_uuid(); extra uuid:=gen_random_uuid(); foreign_extra uuid:=gen_random_uuid(); document uuid; first_document uuid; booking uuid;
 today date:=(now() at time zone 'Europe/Paris')::date; shooting date:=today+10; project uuid:='00000000-0000-4000-8000-0000000070e0'; actor uuid:='00000000-0000-4000-8000-00000000c0c0';
 parents jsonb:='{"first":{"prenom":"Parent","nom":"Un","adresse":"1 rue de Test","telephone":"0600000001","email":"parent1@example.test"},"second":{"prenom":"Parent","nom":"Deux","adresse":"2 rue de Test","telephone":"0600000002","email":"parent2@example.test"}}';
 path text; previous text; original_hash text;
begin begin
 insert into public.figurants(id,prenom,nom,email,date_naissance) values(child,'Dossier','Mineur','dossier@example.test',(today-interval '15 years')::date),(older,'Dossier','Adolescent','adolescent@example.test',(today-interval '17 years')::date);
 insert into public.projets(id,nom,owner_id) values(other_project,'Autre projet fixture',actor);
 set local role service_role;
 perform public.save_minor_guardians(child,parents);
 perform public.save_minor_guardians(older,jsonb_set(parents,'{second}','{"absence_reason":"decede"}'));
 begin insert into public.bookings(figurant_id,projet_id,date) values(child,project,shooting); raise exception using errcode='ZX002',message='Booking sans dossier accepté'; exception when check_violation then null; end;
 insert into public.minor_dossiers(id,projet_id,figurant_id,tournage_debut,tournage_fin) values(dossier,project,child,shooting,shooting+5),(dossier2,project,older,null,null);
 insert into public.minor_links(dossier_id,token_hash,kind) values(dossier,repeat('a',64),'guardian_1');
 assert public.consume_minor_upload(repeat('a',64),'guardian_2') is null,'Dépôt pour autre représentant autorisé';
 insert into public.minor_requirements(id,projet_id,label) values(foreign_extra,other_project,'Pièce étrangère');
 assert public.consume_minor_upload(repeat('a',64),'extra_'||foreign_extra) is null,'Pièce autre projet autorisée';
 assert public.consume_minor_upload(repeat('a',64),'guardian_1')=dossier,'Dépôt du représentant refusé';
 path:=dossier::text||'/test.pdf';
 insert into storage.objects(bucket_id,name) values('minor-documents',path);
 begin perform public.commit_minor_upload(repeat('a',64),'guardian_1',dossier2::text||'/foreign.pdf','test.pdf','application/pdf'); raise exception using errcode='ZX002',message='Chemin étranger accepté'; exception when raise_exception then null; end;
 previous:=public.commit_minor_upload(repeat('a',64),'guardian_1',path,'test.pdf','application/pdf');
 assert previous is null,'Premier dépôt a une ancienne pièce';
 select id into document from public.minor_documents where dossier_id=dossier and source_key='guardian_1';
 assert (select state='received' from public.minor_documents where id=document),'Dépôt validé automatiquement';
 first_document:=document;
 perform public.review_minor_document(document,'validated',null,actor,null,(select storage_path from public.minor_documents where id=document),(select case md.source_key when 'guardian_1' then public.minor_guardian_fingerprint(dd.figurant_id,1) when 'guardian_2' then public.minor_guardian_fingerprint(dd.figurant_id,2) else null end from public.minor_documents md join public.minor_dossiers dd on dd.id=md.dossier_id where md.id=document));
 original_hash:=public.minor_guardian_fingerprint(child,1::smallint);
 insert into storage.objects(bucket_id,name) values('minor-documents',dossier::text||'/parent2.pdf');
 insert into public.minor_documents(dossier_id,source_key,storage_path,filename,mime_type) values(dossier,'guardian_2',dossier::text||'/parent2.pdf','parent2.pdf','application/pdf') returning id into document;
 perform public.review_minor_document(document,'validated',null,actor,null,(select storage_path from public.minor_documents where id=document),(select case md.source_key when 'guardian_1' then public.minor_guardian_fingerprint(dd.figurant_id,1) when 'guardian_2' then public.minor_guardian_fingerprint(dd.figurant_id,2) else null end from public.minor_documents md join public.minor_dossiers dd on dd.id=md.dossier_id where md.id=document));
 assert not public.minor_dossier_complete(project,child,shooting),'Commission manquante acceptée';
 update public.minor_dossiers set commission_date=today where id=dossier;
 assert public.minor_dossier_complete(project,child,shooting),'Dossier complet refusé';
 insert into public.bookings(figurant_id,projet_id,date) values(child,project,shooting) returning id into booking;
 assert not public.minor_dossier_complete(other_project,child,shooting),'Dossier réutilisé dans autre projet';
 begin delete from public.minor_dossiers where id=dossier; raise exception using errcode='ZX002',message='Dossier supprimé avec fichiers sensibles'; exception when check_violation then null; end;
 begin delete from public.figurants where id=child; raise exception using errcode='ZX002',message='Profil supprimé laissant fichiers orphelins'; exception when check_violation then null; end;
 insert into public.figurant_messages(figurant_id,projet_id,booking_id,sender,corps,categorie) values(child,project,booking,'staff','Fixture convocation','convocation');
 update public.minor_documents set valid_until=shooting-1 where id=document;
 begin insert into public.figurant_messages(figurant_id,projet_id,booking_id,sender,corps,categorie) values(child,project,booking,'staff','Fixture refusée','convocation'); raise exception using errcode='ZX002',message='Convocation mineur après expiration acceptée'; exception when check_violation then null; end;
 begin update public.bookings set date=shooting+1 where id=booking; raise exception using errcode='ZX002',message='Autorisation expirée acceptée'; exception when check_violation then null; end;
 update public.minor_documents set valid_until=shooting+5 where id=document;
 perform public.save_minor_guardians(child,parents);
 assert original_hash=public.minor_guardian_fingerprint(child,1::smallint),'Coordonnées inchangées invalidées';
 perform public.save_minor_guardians(child,jsonb_set(parents,'{first,email}','"changed@example.test"'));
 assert not public.minor_dossier_complete(project,child,shooting),'Ancienne autorisation après changement de représentant acceptée';
 begin perform public.review_minor_document(first_document,'validated',null,actor,null,(select storage_path from public.minor_documents where id=first_document),original_hash); raise exception using errcode='ZX002',message='Validation sur anciennes coordonnées acceptée'; exception when raise_exception then null; end;
 assert (select guardian_fingerprint=original_hash from public.minor_documents where id=first_document),'Empreinte remplacée malgré refus';
 perform public.save_minor_guardians(child,parents);
 insert into public.minor_requirements(id,projet_id,label) values(extra,project,'Pièce supplémentaire');
 assert not public.minor_dossier_complete(project,child,shooting),'Pièce obligatoire ignorée';
 insert into storage.objects(bucket_id,name) values('minor-documents',dossier::text||'/extra.pdf');
 insert into public.minor_documents(dossier_id,source_key,storage_path,filename,mime_type) values(dossier,'extra_'||extra,dossier::text||'/extra.pdf','extra.pdf','application/pdf') returning id into document;
 perform public.review_minor_document(document,'validated',shooting+5,actor,null,(select storage_path from public.minor_documents where id=document),(select case md.source_key when 'guardian_1' then public.minor_guardian_fingerprint(dd.figurant_id,1) when 'guardian_2' then public.minor_guardian_fingerprint(dd.figurant_id,2) else null end from public.minor_documents md join public.minor_dossiers dd on dd.id=md.dossier_id where md.id=document));
 assert public.minor_dossier_complete(project,child,shooting),'Pièce supplémentaire valide refusée';

 insert into storage.objects(bucket_id,name) values('minor-documents',dossier2::text||'/parent.pdf');
 insert into public.minor_documents(dossier_id,source_key,storage_path,filename,mime_type) values(dossier2,'guardian_1',dossier2::text||'/parent.pdf','parent.pdf','application/pdf') returning id into document;
 perform public.review_minor_document(document,'validated',null,actor,null,(select storage_path from public.minor_documents where id=document),(select case md.source_key when 'guardian_1' then public.minor_guardian_fingerprint(dd.figurant_id,1) when 'guardian_2' then public.minor_guardian_fingerprint(dd.figurant_id,2) else null end from public.minor_documents md join public.minor_dossiers dd on dd.id=md.dossier_id where md.id=document));
 assert public.minor_dossier_complete(project,older,shooting),'Les 16-18 ans doivent seulement fournir les autorisations, sans les pièces DRIEETS supplémentaires';
 update public.minor_requirements set active=false where id=extra;
 insert into public.bookings(figurant_id,projet_id,date) values(older,project,shooting);
 update public.minor_links set revoked_at=now() where token_hash=repeat('a',64);
 assert public.consume_minor_upload(repeat('a',64),'guardian_1') is null,'Lien révoqué utilisable';
 begin perform public.commit_minor_upload(repeat('a',64),'guardian_1',path,'test.pdf','application/pdf'); raise exception using errcode='ZX002',message='Dépôt terminé après révocation'; exception when raise_exception then null; end;
 insert into public.minor_links(dossier_id,token_hash,kind,created_at,expires_at) values(dossier,repeat('b',64),'guardian_1',now()-interval '2 days',now()-interval '1 day');
 assert public.consume_minor_upload(repeat('b',64),'guardian_1') is null,'Lien expiré utilisable';
 insert into public.minor_links(dossier_id,token_hash,kind,upload_count) values(dossier,repeat('c',64),'guardian_1',30),(dossier,repeat('d',64),'production',0);
 assert public.consume_minor_upload(repeat('c',64),'guardian_1') is null,'Quota ignoré';
 assert public.consume_minor_upload(repeat('d',64),'guardian_1') is null,'Lien production permet un dépôt';
 reset role;
 create policy fixture_broad_read on storage.objects for select to anon,authenticated using(true);
 grant select on storage.objects to anon,authenticated;
 set local role anon;
 assert not exists(select 1 from storage.objects where bucket_id='minor-documents'),'Ancienne policy large contourne le bucket privé';
 reset role;
 set local role authenticated;
 assert not exists(select 1 from storage.objects where bucket_id='minor-documents'),'Staff générique contourne le bucket privé';
 reset role;
 assert not has_table_privilege('anon','public.minor_documents','select'),'Pièces publiques';
 assert not has_table_privilege('authenticated','public.minor_links','select'),'Liens accessibles directement au staff';
 assert not has_function_privilege('authenticated','public.minor_dossier_complete(uuid,uuid,date)','execute'),'Dossier exposé en RPC';
 assert not (select public from storage.buckets where id='minor-documents'),'Bucket public';
 raise exception using errcode='ZX001',message='Rollback fixtures';
exception when sqlstate 'ZX001' then raise notice 'PASS dossiers par projet, autorisations/signatures, expiration, changements représentants, pièces supplémentaires, blocages bookings, liens/quota/révocation et confidentialité; fixtures annulées'; end;
end $test$;
